import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Observable, map, of, switchMap, tap } from 'rxjs';
import { PeopleService } from './people.service';
import { due } from './rates.service';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export interface Claim {
  id: number;
  personId: number;
  /** Text with two decimals, e.g. "10.00". */
  amount: string;
  /** yyyy-MM-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when opened; null while a draft and once voided. */
  number: string | null;
  /** A settled claim's due, fixed when it was settled, as text with two decimals; null while live, or when its grade had no rate then (it then follows the rates). */
  due: string | null;
  /** The user who opened it; null while a draft. They may not settle it. */
  openedBy: string | null;
  /** Bound by its person's last statement: it shows and totals `statedDue` until the next one. */
  stated: boolean;
  /** The figure it had at that statement, as text with two decimals; null when it had none (n/a). */
  statedDue: string | null;
  /** A correction's (negative amount) number of the settled claim of the same person it corrects; null otherwise. */
  corrects: string | null;
}

/** What a bulk open did: how many claims were opened and how many refused. */
export interface BulkOpened {
  opened: number;
  refused: number;
}

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A change of status a claim's buttons ask for. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** Only open and settled claims count toward claimed and due; drafts and voided claims do not. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'SETTLED';
}

/** A claim keeps a figure that does not follow the rates: settled with a fixed due, or bound by a statement to one (not n/a). */
export function fixed(c: Claim): boolean {
  return c.due !== null || (c.stated && c.statedDue !== null);
}

/** What an overdue claim's late charge follows: the terms (days), the sheet's today (yyyy-MM-dd; null: none loaded) and the late percent (in hundredths of a percent). */
export interface LateTerms {
  terms: number;
  today: string | null;
  pct: number;
}

/**
 * A claim's due in cents: a settled claim's fixed figure (any late charge frozen in), else the figure
 * its person's last statement bound it to, otherwise its amount times the rate in force on its date
 * (looked up by `rateOn`, in hundredths of a percent), raised to the sheet's floor (in cents) unless a correction;
 * undefined when it has none. An overdue claim's figure gains its late charge on top (never bound).
 * Its live figures round half up when `halfUp` says so for it, else half to even.
 */
export function claimDue(
  c: Claim, rateOn: (date: string) => number | undefined, floor: number, late?: LateTerms,
  halfUp: (c: Claim) => boolean = () => false,
): number | undefined {
  if (c.due !== null) return cents(c.due);
  const up = halfUp(c);
  const figure = baseDue(c, rateOn, floor, up);
  return figure === undefined || !late || correction(c) ? figure : figure + lateCharge(c, figure, late, up);
}

function baseDue(
  c: Claim, rateOn: (date: string) => number | undefined, floor: number, halfUp: boolean,
): number | undefined {
  if (c.stated) return c.statedDue === null ? undefined : cents(c.statedDue);
  const rate = rateOn(c.date);
  if (rate === undefined) return undefined;
  const d = due(cents(c.amount), rate, halfUp);
  return correction(c) ? d : Math.max(d, floor);
}

/** A correction: a negative amount; its due has no floor and no late charge. */
export function correction(c: Claim): boolean {
  return c.amount.startsWith('-');
}

/** The late charge in cents on a figure: the late percent of it for every full 30 days the claim is overdue, rounded like due. */
export function lateCharge(c: Claim, figure: number, late: LateTerms, halfUp = false): number {
  if (late.today === null || !overdue(c, late.terms, late.today)) return 0;
  const days = (Date.parse(late.today) - Date.parse(dueBy(c, late.terms))) / 86_400_000;
  return due(figure, late.pct * Math.floor(days / 30), halfUp);
}

/** The date (yyyy-MM-dd) a claim is due by: its date plus the terms (days). */
export function dueBy(c: Claim, terms: number): string {
  const [y, m, d] = c.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** A claim is overdue when it is open and its due-by is before the sheet's today (yyyy-MM-dd; null: none loaded). */
export function overdue(c: Claim, terms: number, today: string | null): boolean {
  return today !== null && c.status === 'OPEN' && dueBy(c, terms) < today;
}

export interface ClaimForm {
  amount: string;
  /** null: the sheet's today. */
  date: string | null;
  note: string;
  /** For a correction (a negative amount): the number of the settled claim it corrects. */
  corrects: string | null;
}

// The active sheet's claims, newest first, and what they add up to (kept in cents so sums are exact).
@Injectable({ providedIn: 'root' })
export class ClaimsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly people = inject(PeopleService);
  private readonly list = signal<Claim[]>([]);

  readonly claims = this.list.asReadonly();

  /** The ids of the claims chosen for a bulk open. */
  readonly selected = signal<ReadonlySet<number>>(new Set());

  /** Choose a claim for a bulk open, or leave it out. */
  select(claimId: number, on: boolean): void {
    this.selected.update((all) => {
      const out = new Set(all);
      if (on) out.add(claimId);
      else out.delete(claimId);
      return out;
    });
  }

  /** The ids of the people on hold. */
  private readonly heldIds = computed(
    () => new Set(this.people.people().filter((p) => p.held).map((p) => p.id)),
  );

  /** Whether a claim counts in the live totals: open and settled ones do, except a held person's open ones. */
  readonly live = computed(() => {
    const held = this.heldIds();
    return (c: Claim) => counts(c) && !(c.status === 'OPEN' && held.has(c.personId));
  });

  /** Each person's claims, newest first. */
  readonly byPerson = computed(() => {
    const out = new Map<number, Claim[]>();
    for (const c of this.list()) out.set(c.personId, [...(out.get(c.personId) ?? []), c]);
    return out;
  });

  /** Each person's claimed (live claims), in cents. */
  readonly claimedCents = computed(() => {
    const out = new Map<number, number>();
    for (const c of this.list().filter(this.live())) out.set(c.personId, (out.get(c.personId) ?? 0) + cents(c.amount));
    return out;
  });

  /** Everyone's claimed (live claims) added up, in cents. */
  readonly totalCents = computed(() => this.list().filter(this.live()).reduce((sum, c) => sum + cents(c.amount), 0));

  /**
   * The date a claim rounds by: a correction's is the date of the claim it corrects (its own when
   * that is not found), any other claim's its own.
   */
  readonly roundingDate = computed(() => {
    const byNumber = new Map<string, string>();
    for (const c of this.list()) if (c.number !== null) byNumber.set(`${c.personId}:${c.number}`, c.date);
    return (c: Claim) => (c.corrects === null ? c.date : byNumber.get(`${c.personId}:${c.corrects}`) ?? c.date);
  });

  /** Re-read the active sheet's claims from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Claim[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((claims) => {
        if (this.sheets.sheetId() !== id) return;
        this.list.set(claims);
        const ids = new Set(claims.map((c) => c.id));
        this.selected.update((all) => new Set([...all].filter((c) => ids.has(c))));
      }));
  }

  add(personId: number, form: ClaimForm): Observable<Claim> {
    const sheet = this.sheet();
    return this.http
      .post<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/claims`, form, {
        headers: this.session.headers(),
      })
      .pipe(tap((c) => this.list.update((all) => [c, ...all])));
  }

  /**
   * Add a draft claim of this amount, dated the sheet's today, for the person with this name; one
   * not on the sheet is added first with grade A. The caller re-reads the people.
   */
  quickAdd(name: string, amount: string): Observable<Claim> {
    const sheet = this.sheet();
    return this.http
      .post<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, { name, amount }, {
        headers: this.session.headers(),
      })
      .pipe(tap((c) => this.list.update((all) => [c, ...all])));
  }

  /** Take a statement for a person, binding their counting claims; the caller re-reads the people. */
  statement(personId: number): Observable<Claim[]> {
    const sheet = this.sheet();
    return this.http
      .post<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/statement`, null, {
        headers: this.session.headers(),
      })
      .pipe(tap((theirs) => {
        const byId = new Map(theirs.map((c) => [c.id, c]));
        this.list.update((all) => all.map((o) => byId.get(o.id) ?? o));
      }));
  }

  edit(claimId: number, form: ClaimForm): Observable<Claim> {
    return this.http
      .put<Claim>(`${this.url(this.sheet())}/${claimId}`, form, { headers: this.session.headers() })
      .pipe(tap((c) => this.list.update((all) => all.map((o) => (o.id === c.id ? c : o)))));
  }

  changeStatus(claimId: number, action: ClaimAction): Observable<Claim> {
    return this.http
      .post<Claim>(`${this.url(this.sheet())}/${claimId}/${action}`, null, { headers: this.session.headers() })
      .pipe(tap((c) => this.list.update((all) => all.map((o) => (o.id === c.id ? c : o)))));
  }

  /** Open the chosen claims that can be opened, numbered in list order; then re-read the claims. */
  bulkOpen(claimIds: readonly number[]): Observable<BulkOpened> {
    return this.http
      .post<BulkOpened>(`${this.url(this.sheet())}/bulk-open`, { claimIds }, { headers: this.session.headers() })
      .pipe(switchMap((r) => this.reload().pipe(map(() => r))));
  }

  private sheet(): string {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return id;
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/claims`;
  }
}

/** "12.34" as 1234. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const out = Number(whole) * 100 + Number((frac + '00').slice(0, 2));
  return negative ? -out : out;
}

/** 1234 as "12.34". */
export function money(cents: number): string {
  const abs = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}
import { Injectable, computed, inject } from '@angular/core';
import { Claim, ClaimsService, claimDue, money } from './claims.service';
import { Grade, PeopleService, Person, gradeOn } from './people.service';
import { PeriodsService } from './periods.service';
import { RatesService } from './rates.service';
import { SettingsService } from './settings.service';
import { SheetService } from './sheet.service';

// The due-totals the screen shows, worked out once so the people list, the periods list and the
// summary all agree.
@Injectable({ providedIn: 'root' })
export class TotalsService {
  private readonly people = inject(PeopleService);
  private readonly claims = inject(ClaimsService);
  private readonly periods = inject(PeriodsService);
  private readonly rates = inject(RatesService);
  private readonly settings = inject(SettingsService);
  private readonly sheets = inject(SheetService);

  /**
   * Whether a claim's live figures round half up: it rounds by a date before the policy date in force
   * (the sheet's today when none is set); else they round half to even.
   */
  readonly halfUp = computed(() => {
    const policy = this.settings.policyInForce();
    const roundingDate = this.claims.roundingDate();
    return (c: Claim) => policy !== null && roundingDate(c) < policy;
  });

  /**
   * Each person's due-total in cents: the sum of their open and settled claims' dues (those with one);
   * absent when the grade in force on today has no rate in force then and none of those claims has a due.
   */
  readonly personDueTotals = computed(() => {
    const out = new Map<number, number>();
    const floor = this.settings.floorCents();
    const late = this.settings.late();
    const halfUp = this.halfUp();
    for (const p of this.people.people()) {
      const counted = (this.claims.byPerson().get(p.id) ?? []).filter(this.claims.live());
      const rateOn = (date: string) => this.rateOn(p, date);
      const dues = counted.map((c) => claimDue(c, rateOn, floor, late, halfUp));
      const grade = this.gradeToday(p);
      if (!(grade && this.rates.byGrade().has(grade)) && dues.every((d) => d === undefined)) continue;
      out.set(p.id, dues.reduce<number>((sum, d) => sum + (d ?? 0), 0));
    }
    return out;
  });

  /** Each open period's live due-total in cents, by period id: the dues of the counting claims dated in it. */
  private readonly livePeriodTotals = computed(() => {
    const people = new Map(this.people.people().map((p) => [p.id, p]));
    const out = new Map<number, number>();
    const floor = this.settings.floorCents();
    const late = this.settings.late();
    const halfUp = this.halfUp();
    for (const c of this.claims.claims().filter(this.claims.live())) {
      const period = this.periods.periodOn(c.date);
      const p = people.get(c.personId);
      if (!period || !p) continue;
      const d = claimDue(c, (date) => this.rateOn(p, date), floor, late, halfUp);
      out.set(period.id, (out.get(period.id) ?? 0) + (d ?? 0));
    }
    return out;
  });

  /** Each period's due-total as shown, by period id: the one fixed when it closed, else the live one. */
  readonly periodDueTotals = computed(() => {
    const live = this.livePeriodTotals();
    return new Map(this.periods.periods().map((p) => [
      p.id,
      p.closed ? (p.closedTotal ?? '') : money(live.get(p.id) ?? 0),
    ]));
  });

  /** The grade in force on the sheet's today. */
  gradeToday(p: Person): Grade | undefined {
    const today = this.sheets.today();
    return today === null ? p.grade : gradeOn(p.grades, today);
  }

  /** The rate in force on a date for the person's grade in force then, in hundredths of a percent. */
  rateOn(p: Person, date: string): number | undefined {
    const grade = gradeOn(p.grades, date);
    return grade && this.rates.rateOn(grade, date);
  }
}
import { Component, computed, inject, input, signal } from '@angular/core';
import { HttpErrorResponse } from '@angular/common/http';
import { finalize } from 'rxjs';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Claim, ClaimAction, ClaimsService, claimDue, dueBy, money, overdue } from '../../core/claims.service';
import { GradeFrom, gradeOn } from '../../core/people.service';
import { PeriodsService } from '../../core/periods.service';
import { RatesService } from '../../core/rates.service';
import { SessionService } from '../../core/session.service';
import { SettingsService } from '../../core/settings.service';
import { SheetService } from '../../core/sheet.service';
import { TotalsService } from '../../core/totals.service';

// A person's claims, newest first, each with its status and buttons to open, settle or void it, who opened it (they may not settle it, nor may a clerk one whose due is above the sheet's clerk limit), its due (n/a when the person's grade in force on the claim's date has no rate in force then), whether their last statement bound it (it then shows the figure it had then), the period its date falls in (none: empty), the date it is due by (its date plus the sheet's terms), whether it is overdue (open and due before the sheet's today) and, for a correction (a negative amount), the number of the settled claim it corrects, and a form that adds a claim or edits the draft opened (any other claim is refused: void it and add a new one; so is one dated in a closed period).
@Component({
  selector: 'app-person-claims',
  imports: [ReactiveFormsModule],
  template: `
    <ul [attr.aria-label]="'Claims of ' + personName()">
      @for (c of claims(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <input type="checkbox" data-testid="claim-select" [checked]="service.selected().has(c.id)"
            (change)="service.select(c.id, $any($event.target).checked)"
            [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date" />
          <span data-testid="claim-amount">{{ c.amount }}</span>
          <span data-testid="claim-date">{{ c.date }}</span>
          <span data-testid="claim-note">{{ c.note }}</span>
          <span>Due <span data-testid="claim-due">{{ dueOf(c) }}</span></span>
          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
          <span>Status <span data-testid="claim-status">{{ c.status }}</span></span>
          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
          <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
          <span>Period <span data-testid="claim-period">{{ periods.periodOn(c.date)?.name ?? '' }}</span></span>
          <span>Due by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span></span>
          <span>Overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span></span>
          <span>Corrects <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span></span>
          <button type="button" data-testid="claim-edit" (click)="open(c)"
            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
          @for (a of actions; track a.action) {
            <button type="button" [attr.data-testid]="'claim-' + a.action" (click)="change(c, a.action)"
              [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date">{{ a.label }}</button>
          }
          @if (claimErrors().get(c.id); as e) {
            <p role="alert" data-testid="claim-error">{{ e }}</p>
          }
        </li>
      }
    </ul>
    <form [formGroup]="form" (ngSubmit)="submit()"
      [attr.aria-label]="(editing() === null ? 'Add claim for ' : 'Edit claim of ') + personName()">
      <label [for]="'claim-form-amount-' + personId()">Amount</label>
      <input [id]="'claim-form-amount-' + personId()" data-testid="claim-form-amount" formControlName="amount"
        inputmode="decimal" />
      <label [for]="'claim-form-date-' + personId()">Date (empty: today)</label>
      <input [id]="'claim-form-date-' + personId()" type="date" data-testid="claim-form-date" formControlName="date" />
      <label [for]="'claim-form-note-' + personId()">Note</label>
      <input [id]="'claim-form-note-' + personId()" data-testid="claim-form-note" formControlName="note" />
      <label [for]="'claim-form-corrects-' + personId()">Corrects claim no. (negative amount only)</label>
      <input [id]="'claim-form-corrects-' + personId()" data-testid="claim-form-corrects" formControlName="corrects"
        inputmode="numeric" />
      <button type="submit" data-testid="claim-form-submit">{{ editing() === null ? 'Add claim' : 'Save claim' }}</button>
      @if (editing() !== null) {
        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
      }
      @if (error()) {
        <p role="alert" data-testid="claim-form-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class PersonClaims {
  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** The person's grades, each from its date. */
  readonly grades = input.required<readonly GradeFrom[]>();
  protected readonly service = inject(ClaimsService);
  private readonly rates = inject(RatesService);
  private readonly session = inject(SessionService);
  private readonly settings = inject(SettingsService);
  private readonly sheets = inject(SheetService);
  private readonly totals = inject(TotalsService);
  protected readonly periods = inject(PeriodsService);
  protected readonly claims = computed(() => this.service.byPerson().get(this.personId()) ?? []);
  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
    note: new FormControl('', { nonNullable: true }),
    corrects: new FormControl('', { nonNullable: true }),
  });
  protected readonly editing = signal<number | null>(null);
  protected readonly error = signal('');
  /** A submit is waiting for its answer; another submit meanwhile is ignored. */
  private saving = false;
  /** Each claim's refused status change, by claim id; cleared by the next action on that claim. */
  protected readonly claimErrors = signal<ReadonlyMap<number, string>>(new Map());
  protected readonly actions: readonly { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  /** A settled claim shows the due fixed when it was settled, a stated one the figure it was bound to; any other (or one settled without a rate) follows the rate in force on its date, at least the floor. */
  protected dueOf(c: Claim): string {
    const rateOn = (date: string) => {
      const grade = gradeOn(this.grades(), date);
      return grade && this.rates.rateOn(grade, date);
    };
    const d = claimDue(c, rateOn, this.settings.floorCents(),
      this.settings.late(), this.totals.halfUp());
    return d === undefined ? 'n/a' : money(d);
  }

  protected dueByOf(c: Claim): string {
    return dueBy(c, this.settings.terms());
  }

  protected overdueOf(c: Claim): boolean {
    return overdue(c, this.settings.terms(), this.sheets.today());
  }

  protected change(c: Claim, action: ClaimAction): void {
    this.setClaimError(c.id, '');
    this.service.changeStatus(c.id, action).subscribe({
      error: (e: unknown) => this.setClaimError(c.id,
        e instanceof HttpErrorResponse && e.status === 403
          ? c.openedBy === this.session.user()
            ? 'You opened this claim, so someone else must settle it.'
            : 'A clerk cannot settle a claim whose due is above the clerk limit.'
          : `A ${c.status} claim cannot be changed that way.`),
    });
  }

  private setClaimError(claimId: number, message: string): void {
    this.claimErrors.update((all) => {
      const out = new Map(all);
      if (message) out.set(claimId, message);
      else out.delete(claimId);
      return out;
    });
  }

  protected open(c: Claim): void {
    this.setClaimError(c.id, '');
    if (c.status !== 'DRAFT') {
      this.setClaimError(c.id, `A ${c.status} claim cannot be edited; void it and add a new one.`);
      return;
    }
    if (this.periods.periodOn(c.date)?.closed) {
      this.setClaimError(c.id, 'A claim dated in a closed period cannot be edited.');
      return;
    }
    this.error.set('');
    this.editing.set(c.id);
    this.form.setValue({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' },
      { emitEvent: false });
  }

  protected reset(): void {
    this.error.set('');
    this.editing.set(null);
    this.form.reset({ amount: '', date: '', note: '', corrects: '' }, { emitEvent: false });
  }

  protected submit(): void {
    if (this.saving) return;
    this.error.set('');
    const { amount, date, note, corrects } = this.form.getRawValue();
    const a = amount.trim();
    if (!/^-?\d{1,13}(\.\d{1,2})?$/.test(a)) {
      this.error.set('Enter an amount with up to two decimals.');
      return;
    }
    const k = corrects.trim();
    if (a.startsWith('-') && k === '') {
      this.error.set('A negative amount is a correction: give the number of the settled claim it corrects.');
      return;
    }
    const form = { amount: a, date: date.trim() || null, note: note.trim(), corrects: k && a.startsWith('-') ? k : null };
    const id = this.editing();
    const saved = id === null ? this.service.add(this.personId(), form) : this.service.edit(id, form);
    this.saving = true;
    saved.pipe(finalize(() => (this.saving = false))).subscribe({
      next: () => this.reset(),
      error: () => this.error.set(id === null ? 'Could not add that claim.' : 'Could not save that claim.'),
    });
  }
}

